import { readImageMetadata } from '../engines/imageMetadata'
import { toolError } from '../registry'
import { verifyOutput, type VerifiedOutput, type VerifiableOutput } from './verify'

/** Decode generated bytes before success; magic alone cannot prove an image is readable. */
export async function verifyRasterImage(output: VerifiableOutput, expected: { width: number; height: number }): Promise<VerifiedOutput> {
  let bitmap: ImageBitmap | undefined
  try {
    const metadata = readImageMetadata(output.bytes)
    const mime = metadata.kind === 'jpeg' ? 'image/jpeg' : 'image/png'
    if (mime !== output.mimeType || metadata.width !== expected.width || metadata.height !== expected.height) throw new Error('Incorrect image format or dimensions')
    if (typeof createImageBitmap !== 'function') throw toolError('E-SYS-01', 'Image verification is unavailable in this browser.', 'suggest-browser')
    bitmap = await createImageBitmap(new Blob([Uint8Array.from(output.bytes).buffer], { type: mime }))
    if (bitmap.width !== expected.width || bitmap.height !== expected.height) throw new Error('Decoded image dimensions differ')
    return await verifyOutput(output)
  } catch (error) {
    if ((error as { code?: string }).code === 'E-SYS-01') throw error
    throw toolError('E-OUT-01', 'The generated image failed format, decoding or dimension verification.', 'retry-job')
  } finally { bitmap?.close() }
}
